class Solution:
    def subtreeInversionSum(self, edges: List[List[int]], nums: List[int], k: int) -> int:
        n = len(nums)
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v); adj[v].append(u)
        order, par = [], [-1] * n
        stack = [0]
        seen = [False] * n
        seen[0] = True
        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                if not seen[v]:
                    seen[v] = True; par[v] = u; stack.append(v)
        NEG = float('-inf')
        dp = [[[NEG, NEG] for _ in range(k + 1)] for _ in range(n)]
        for u in reversed(order):
            kids = [v for v in adj[u] if v != par[u]]
            for d in range(k + 1):
                for s in range(2):
                    sg = 1 if s == 0 else -1
                    if d > 0:
                        tot = sg * nums[u]
                        for v in kids: tot += dp[v][d - 1][s]
                        dp[u][d][s] = tot
                    else:
                        best = sg * nums[u]
                        for v in kids: best += dp[v][0][s]
                        alt = -sg * nums[u]
                        for v in kids: alt += dp[v][k - 1][1 - s]
                        dp[u][d][s] = max(best, alt)
        return dp[0][0][0]

