class Solution {
public:
    long long subtreeInversionSum(vector<vector<int>>& edges, vector<int>& nums, int k) {
        int n = nums.size();
        vector<vector<int>> adj(n);
        for (auto &e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        vector<int> par(n, -1), order;
        vector<bool> seen(n, false);
        vector<int> st = {0}; seen[0] = true;
        while (!st.empty()) {
            int u = st.back(); st.pop_back(); order.push_back(u);
            for (int v : adj[u]) if (!seen[v]) { seen[v] = true; par[v] = u; st.push_back(v); }
        }
        const long long NEG = LLONG_MIN / 4;
        vector<array<array<long long,2>,51>> dp(n);
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            vector<int> kids;
            for (int v : adj[u]) if (v != par[u]) kids.push_back(v);
            for (int d = 0; d <= k; d++) for (int s = 0; s < 2; s++) {
                long long sg = s ? -1 : 1;
                if (d > 0) {
                    long long tot = sg * nums[u];
                    for (int v : kids) tot += dp[v][d - 1][s];
                    dp[u][d][s] = tot;
                } else {
                    long long best = sg * nums[u];
                    for (int v : kids) best += dp[v][0][s];
                    long long alt = -sg * nums[u];
                    for (int v : kids) alt += dp[v][k - 1][1 - s];
                    dp[u][d][s] = max(best, alt);
                }
            }
        }
        return dp[order[0]][0][0];
    }
};

