class Solution {
    public long subtreeInversionSum(int[][] edges, int[] nums, int k) {
        int n = nums.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] par = new int[n]; Arrays.fill(par, -1);
        List<Integer> order = new ArrayList<>();
        boolean[] seen = new boolean[n];
        Deque<Integer> st = new ArrayDeque<>(); st.push(0); seen[0] = true;
        while (!st.isEmpty()) {
            int u = st.pop(); order.add(u);
            for (int v : adj.get(u)) if (!seen[v]) { seen[v] = true; par[v] = u; st.push(v); }
        }
        long NEG = Long.MIN_VALUE / 4;
        long[][][] dp = new long[n][k + 1][2];
        for (int i = n - 1; i >= 0; i--) {
            int u = order.get(i);
            List<Integer> kids = new ArrayList<>();
            for (int v : adj.get(u)) if (v != par[u]) kids.add(v);
            for (int d = 0; d <= k; d++) for (int s = 0; s < 2; s++) {
                long sg = s == 0 ? 1 : -1;
                if (d > 0) {
                    long tot = sg * nums[u];
                    for (int v : kids) tot += dp[v][d - 1][s];
                    dp[u][d][s] = tot;
                } else {
                    long best = sg * nums[u];
                    for (int v : kids) best += dp[v][0][s];
                    long alt = -sg * nums[u];
                    for (int v : kids) alt += dp[v][k - 1][1 - s];
                    dp[u][d][s] = Math.max(best, alt);
                }
            }
        }
        return dp[0][0][0];
    }
}

