var subtreeInversionSum = function(edges, nums, k) {
    const n = nums.length;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
    const par = new Array(n).fill(-1), order = [], seen = new Array(n).fill(false);
    const st = [0]; seen[0] = true;
    while (st.length) {
        const u = st.pop(); order.push(u);
        for (const v of adj[u]) if (!seen[v]) { seen[v] = true; par[v] = u; st.push(v); }
    }
    const NEG = -Infinity;
    const dp = Array.from({length: n}, () => Array.from({length: k + 1}, () => [NEG, NEG]));
    for (let i = n - 1; i >= 0; i--) {
        const u = order[i], kids = [];
        for (const v of adj[u]) if (v !== par[u]) kids.push(v);
        for (let d = 0; d <= k; d++) for (let s = 0; s < 2; s++) {
            const sg = s ? -1 : 1;
            if (d > 0) {
                let tot = sg * nums[u];
