                dp[u][d][s] = tot;
            } else {
                let best = sg * nums[u];
                for (const v of kids) best += dp[v][0][s];
                let alt = -sg * nums[u];
                for (const v of kids) alt += dp[v][k - 1][1 - s];
                dp[u][d][s] = Math.max(best, alt);
            }
        }
    }
    return dp[0][0][0];
};
